function autocomplete(itm){$(itm).typeahead(t_settings,{name:"Key-"+idx,limit:10,source:substringMatcher(hints)})}window.substringMatcher=function(strs){return function(q,cb){var matches;matches=[],substrRegex=new RegExp(q,"i"),$.each(strs,function(i,str){substrRegex.test(str)&&matches.push(str)}),cb(matches)}};var t_settings={hint:!1,highlight:!0,classNames:{menu:"dropdown-menu suggestion-list",suggestion:"suggestion-item"}};$(document).ready(function(){$.getJSON("/admin/Products/LoadHints",function(response){hints=response.data,autocomplete(".typeahead")}),$("#Shipping").on("change",function(){$(this).is(":checked")?($("#IsFreeShipping").prop("disabled",!1),$(".shipping_inputs input").each((indx,itm)=>$(itm).prop("disabled",!1))):($("#IsFreeShipping").prop("disabled",!0).prop("checked",!1),$(".shipping_inputs input").each((indx,itm)=>$(itm).prop("disabled",!0).val(0)))}),$("#publish_product").on("change",function(e){var $this=$(this);$.get("/Admin/Products/Publish/"+pid).done(function(res){res.success&&($this.is(":checked")?$notification.success("","Published successfully",2e3,"fa fa-check"):$notification.warning("","Unpublished successfully",2e3,"fa fa-check"))}).fail(function(jqXHR,Status){$notification.error("Error!",jqXHR.statusText,2e3,"fa fa-exclamation-circle")})}),$(document).on("click",".delete-product",function(e){e.preventDefault();$(this);$Confirm(function(result){result.value&&$.ajax({url:"/Admin/Products/delete/"+pid,type:"Get",dataType:"json",data:{redirection:!0}}).done(function(data){data.success?($notification.success("","deleted successfully",2e3,"fa fa-check"),window.location.assign(window.location.origin+"/Admin/products")):$notification.error("Error!","",2e3,"fa fa-exclamation-circle")}).fail(function(jqXHR,Status){$notification.error("Error!",jqXHR.statusText,2e3,"fa fa-exclamation-circle")})})})});